  const body = JSON.parse(String($('build_author_brief').first().json.AUTHOR_BODY || '{}'));
  brief = String((((body.messages || [])[0] || {}).content) || '');
} catch (e) {
  brief = '';
}
const frames = [];
for (let i = 0; i < items.length; i++) {
  const bin = (items[i].binary || {}).data;
  if (!bin) continue;
  const buf = await this.helpers.getBinaryDataBuffer(i, 'data');
  frames.push('data:' + (bin.mimeType || 'image/png') + ';base64,' + buf.toString('base64'));
}
if (!frames.length) throw new Error('the stills could not be read; refusing to review without them');
const content = [{ type: 'text', text: prompt + '\n\n---\n\nThe brief the composer was given:\n' + brief }];
for (const url of frames) content.push({ type: 'image_url', image_url: { url } });
return [{ json: {
  ...a,
  STILL_COUNT: frames.length,
  CRITIQUE_BODY: JSON.stringify({ model: 'opencode-go/glm-5.3-flash', messages: [{ role: 'user', content }] }),
} }];

// The critic's verdict, read tolerantly. Anything unreadable is a pass with the raw answer
// recorded: treating it as "keep fixing" is how a model that cannot hold the format spends
// every cycle and still ships the same defect.
const resp = $input.first().json || {};
const a = $('encode_stills').first().json;
const raw = String((((resp.choices || [])[0] || {}).message || {}).content || '').trim();
let verdict = 'ok';
let findings = [];
let unreadable = true;
const start = raw.indexOf('{');
const end = raw.lastIndexOf('}');
if (start !== -1 && end > start) {
  try {
    const parsed = JSON.parse(raw.slice(start, end + 1));
    const named = (Array.isArray(parsed.findings) ? parsed.findings : [])
      .map((f) => ({ where: String((f && f.where) || '').trim(), what: String((f && f.what) || '').trim(), fix: String((f && f.fix) || '').trim() }))
      .filter((f) => f.fix || f.what);
    if (String(parsed.verdict || '').trim().toLowerCase() === 'fix' && named.length) {
      verdict = 'fix';
      findings = named;
    }
    unreadable = false;
  } catch (e) {
    unreadable = true;
  }
}
const round = Math.max(0, Number(a.REVIEW_ROUND || 0));
const cycles = Math.max(0, Number($('normalize_input').first().json.REVIEW_CYCLES || 0));
const findingsText = findings.map((f, i) => (i + 1) + '. ' + (f.where ? f.where + ': ' : '') + (f.what || 'a defect') + ' - ' + f.fix).join('\n');
return [{ json: {
  ...a,
  VERDICT: verdict,
  FINDINGS_TEXT: findingsText,
  UNREADABLE: unreadable,
  // The loop's whole decision, as data: fix what the critic named, while the budget allows.
  RETRY: verdict === 'fix' && round < cycles,
  REVIEW: JSON.stringify({ round: round + 1, verdict, findings, unreadable, raw: raw.slice(0, 2000) }),
} }];

// The next authoring turn, with the critic's findings as the reviewer's correction. The
// session id is unchanged, so the adapter edits the composition in place rather than
// authoring a new one, and the round is incremented for the bound the gate reads.
const a = $input.first().json;
return [{ json: {
  ...a,
  FEEDBACK: a.FINDINGS_TEXT || '',
  REVIEW_ROUND: Math.max(0, Number(a.REVIEW_ROUND || 0)) + 1,
} }];
